import { useDispatch, useSelector } from 'react-redux';
import { newChat, setActiveChat, deleteChat, selectChats, selectActiveChatId } from '../../store/slices/chatSlice';
import { setSidebarOpen } from '../../store/slices/uiSlice';
import { logout, selectUser } from '../../store/slices/authSlice';
import { Avatar } from '../ui/Avatar';
import IconButton from '../ui/IconButton';
import { useTheme } from '../../hooks/useTheme';

export default function Sidebar() {
  const dispatch   = useDispatch();
  const chats      = useSelector(selectChats);
  const activeId   = useSelector(selectActiveChatId);
  const user       = useSelector(selectUser);
  const { dark, sidebarHex, borderHex, textHex, mutedHex, hoverHex } = useTheme();

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', background: sidebarHex }}>
      {/* Header */}
      <div style={{ padding: '16px 12px 8px', display: 'flex', alignItems: 'center', gap: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1 }}>
          <div style={{ width: 30, height: 30, borderRadius: 8, background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" stroke="white" strokeWidth="2"/><circle cx="9" cy="10.5" r="1.5" fill="white"/><circle cx="15" cy="10.5" r="1.5" fill="white"/><path d="M9 15c.8 1.2 5.2 1.2 6 0" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>
          </div>
          <span style={{ fontFamily: "'Space Grotesk'", fontWeight: 700, fontSize: 16, color: textHex }}>HelixtaAI</span>
        </div>
        <IconButton onClick={() => dispatch(setSidebarOpen(false))} title="Collapse sidebar">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M15 18l-6-6 6-6"/></svg>
        </IconButton>
      </div>

      {/* New Chat Button */}
      <div style={{ padding: '8px 12px' }}>
        <button onClick={() => dispatch(newChat())} style={{
          width: '100%', padding: '10px 14px', borderRadius: 10,
          border: `1px solid ${borderHex}`, background: 'none',
          color: textHex, fontSize: 14, fontFamily: "'DM Sans', sans-serif",
          cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8,
          fontWeight: 500, transition: 'background 0.15s',
        }}
          onMouseEnter={(e) => { e.currentTarget.style.background = hoverHex; }}
          onMouseLeave={(e) => { e.currentTarget.style.background = 'none'; }}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M12 5v14M5 12h14"/></svg>
          New chat
        </button>
      </div>

      {/* Chat List */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '8px 12px' }}>
        <p style={{ fontSize: 11, fontWeight: 600, color: mutedHex, textTransform: 'uppercase', letterSpacing: '0.08em', padding: '4px 8px 8px' }}>Conversations</p>
        {chats.map((c) => (
          <div key={c.id}
            onClick={() => dispatch(setActiveChat(c.id))}
            style={{
              display: 'flex', alignItems: 'center', gap: 10,
              padding: '9px 12px', borderRadius: 10, cursor: 'pointer',
              transition: 'background 0.15s', fontSize: 13.5,
              color: c.id === activeId ? '#6366f1' : textHex,
              background: c.id === activeId ? (dark ? '#22223a' : '#e8e8ff') : 'none',
              justifyContent: 'space-between',
            }}
            onMouseEnter={(e) => { if (c.id !== activeId) e.currentTarget.style.background = hoverHex; }}
            onMouseLeave={(e) => { if (c.id !== activeId) e.currentTarget.style.background = 'none'; }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, flex: 1, overflow: 'hidden' }}>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" style={{ flexShrink: 0 }}><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
              <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flex: 1 }}>{c.title}</span>
            </div>
            <IconButton style={{ padding: 4, opacity: 0.6, flexShrink: 0 }} onClick={(e) => { e.stopPropagation(); dispatch(deleteChat(c.id)); }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg>
            </IconButton>
          </div>
        ))}
      </div>

      {/* User + Logout */}
      <div style={{ padding: '12px', borderTop: `1px solid ${borderHex}` }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 12px', borderRadius: 10 }}>
          <Avatar name={user?.name ?? 'User'} size={32}/>
          <div style={{ flex: 1, overflow: 'hidden' }}>
            <p style={{ fontSize: 13.5, fontWeight: 500, color: textHex, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{user?.name}</p>
            <p style={{ fontSize: 12, color: mutedHex, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{user?.email}</p>
          </div>
          <IconButton title="Logout" onClick={() => dispatch(logout())}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>
          </IconButton>
        </div>
      </div>
    </div>
  );
}
